from bookings import load_bookings, ROWS
from summary import BookingSummary

MEAN = sum(v for _, v in ROWS) / len(ROWS)


def test_mean_of_stored():
    assert abs(BookingSummary(load_bookings()).mean_nights() - MEAN) < 1e-9


def test_count_then_mean():
    s = BookingSummary(load_bookings())
    assert s.count() == len(ROWS) and abs(s.mean_nights() - MEAN) < 1e-9


def test_mean_twice():
    s = BookingSummary(load_bookings())
    s.mean_nights()
    assert abs(s.mean_nights() - MEAN) < 1e-9


def test_list_input():
    assert abs(BookingSummary(list(load_bookings())).mean_nights() - MEAN) < 1e-9


def test_empty():
    assert BookingSummary(iter([])).mean_nights() == 0.0
